<script setup lang="ts">import {computed} from 'vue';import {fixed} from '../utils/format';const props=defineProps<{result:any;mode:'deming'|'ba'}>();const bounds=computed(()=>{const points=props.result.points;const xs=points.map((p:any)=>props.mode==='deming'?(p.x_analysis??p.x):p.mean),ys=points.map((p:any)=>props.mode==='deming'?(p.y_analysis??p.y):p.difference);if(props.mode==='ba')ys.push(props.result.agreement.loa_low,props.result.agreement.loa_high);const xmin=Math.min(...xs),xmax=Math.max(...xs),ymin=Math.min(...ys),ymax=Math.max(...ys);return {xmin:xmin-Math.max((xmax-xmin)*.04,.1),xmax:xmax+Math.max((xmax-xmin)*.04,.1),ymin:ymin-Math.max((ymax-ymin)*.12,.1),ymax:ymax+Math.max((ymax-ymin)*.12,.1)}});const X=(v:number)=>48+(v-bounds.value.xmin)/(bounds.value.xmax-bounds.value.xmin)*590;const Y=(v:number)=>242-(v-bounds.value.ymin)/(bounds.value.ymax-bounds.value.ymin)*210;const line=(a:number,b:number)=>`${X(bounds.value.xmin)},${Y(a+b*bounds.value.xmin)} ${X(bounds.value.xmax)},${Y(a+b*bounds.value.xmax)}`</script><template><div class="agreement-plot"><svg viewBox="0 0 690 290" role="img" :aria-label="mode==='deming'?'Deming校准散点与回归线':'Bland-Altman差值与均值图'"><g v-for="t in [0,.25,.5,.75,1]" :key="t"><line x1="48" x2="638" :y1="32+t*210" :y2="32+t*210" class="gridline"/><text x="1" :y="36+t*210">{{fixed(bounds.ymax-t*(bounds.ymax-bounds.ymin),1)}}</text><text :x="48+t*590" y="265" text-anchor="middle">{{fixed(bounds.xmin+t*(bounds.xmax-bounds.xmin),1)}}</text></g><g v-if="mode==='deming'"><polyline :points="line(0,1)" class="identity-line"/><polyline :points="line(result.deming.intercept,result.deming.slope)" class="fit-line"/></g><g v-else><line v-for="[name,v] in [['上限',result.agreement.loa_high],['偏倚',result.agreement.bias],['下限',result.agreement.loa_low]]" :key="String(name)" x1="48" x2="638" :y1="Y(Number(v))" :y2="Y(Number(v))" :class="name==='偏倚'?'bias-line':'loa-line'"/><polyline v-if="result.agreement.proportional.estimable" :points="line(result.agreement.proportional.intercept,result.agreement.proportional.slope)" class="trend-line"/></g><circle v-for="p in result.points" :key="p.pair_id" :cx="X(mode==='deming'?(p.x_analysis??p.x):p.mean)" :cy="Y(mode==='deming'?(p.y_analysis??p.y):p.difference)" :r="p.outside_loa?3.1:2.4" :class="p.outside_loa?'outlier':'point'"/><text x="340" y="285" text-anchor="middle">{{mode==='deming'?'X探头读数':'两探头均值'}} / {{result.unit}}</text></svg><div class="plot-caption" v-if="mode==='deming'"><span>● 成对观测</span><span>— Deming校准线</span><span>┆ y=x参考线</span></div><div class="plot-caption" v-else><span>— 偏倚与一致性界限</span><span>┆ 差值对均值的比例趋势</span><span>● 界限外观测</span></div></div></template>
